				if m.Ptr+1 >= m.End {
					m.Ptr = m.End
					return depth
				}
				if rt.Ld16(m.Mem, int(m.Ptr)) == open {
					depth++
					m.Ptr += 2
					continue scan
				}
				depth--
				m.Ptr += 2
				if depth == 0 {
					return depth
				}
				continue scan
